fixed_example.code:
create table public.dossiers (
  id uuid primary key default gen_random_uuid(),
  cabinet_id uuid not null,
  contenu text
);

alter table public.dossiers enable row level security;

create policy "lecture limitee au cabinet"
  on public.dossiers
  for select
  to authenticated
  using ( cabinet_id = (select auth.jwt() ->> 'cabinet_id')::uuid );

create function private.a_le_role(role_attendu text)
returns boolean
language plpgsql
security definer set search_path = ''    -- schema prive, chemin fixe
as $$
begin
  return exists (
    select 1 from public.roles_table
    where user_id = (select auth.uid()) and role = role_attendu
  );
end;
$$;

